//! Adattatore stateless della valutazione sul registro servizi esistente.
//!
//! `evaluate_v1` è transitorio: non è il protocollo a finestre della ADR 0201.
//! Non conserva sorgenti tra chiamate e non legge o scrive il vault.

use fub_abi::{HostApi, PluginError, ServiceProvider};
use serde::Deserialize;
use serde_json::Value;

use crate::{session::check_response_size, Workbook};

pub const SERVICE_ID: &str = "fub.sheet";
pub const EVALUATE_METHOD: &str = "evaluate_v1";

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct EvaluationRequest {
    source: String,
}

pub struct SheetService;

impl ServiceProvider for SheetService {
    fn call(
        &self,
        service: &str,
        method: &str,
        args: Value,
        _host: &mut dyn HostApi,
    ) -> Result<Value, PluginError> {
        if service != SERVICE_ID || method != EVALUATE_METHOD {
            return Err(PluginError::BadArgs("unknown sheet service method".into()));
        }
        let request: EvaluationRequest = serde_json::from_value(args)
            .map_err(|error| PluginError::BadArgs(error.to_string().into()))?;
        // Il parser rifiuta più di 16 MiB prima di allocare il modello JSON.
        let workbook = Workbook::parse(&request.source)
            .map_err(|error| PluginError::BadArgs(error.to_string().into()))?;
        let evaluation = workbook
            .evaluate()
            .map_err(|error| PluginError::BadArgs(error.to_string().into()))?;
        // L'escaping conta nel tetto di 8 MiB, anche prima della copia Value.
        check_response_size(&evaluation)
            .map_err(|error| PluginError::BadArgs(error.to_string().into()))?;
        serde_json::to_value(evaluation)
            .map_err(|error| PluginError::Internal(error.to_string().into()))
    }
}

