/// Conta il JSON effettivo prima che il chiamante ne materializzi una copia.
pub(crate) fn check_response_size(value: &impl Serialize) -> Result<(), SheetSessionError> {
    let mut budget = ByteBudget::new(MAX_WINDOW_RESPONSE_BYTES);
    serde_json::to_writer(&mut budget, value).map_err(|error| {
        if budget.exceeded {
            SheetSessionError::ResponseTooLarge
        } else {
            SheetSessionError::Serialization(error)
        }
    })
}

use fub_abi::{PluginError, ServiceProvider};
use fub_format_sheet::{
    service::{SheetService, EVALUATE_METHOD, SERVICE_ID},
    Workbook, MAX_SOURCE_BYTES,
};
use fub_sdk::testing::MemoryHost;
use serde_json::{json, Value};

fn source(input: &str) -> String {
    json!({"version":1,"sheets":[{"id":"s","name":"Foglio","rows":[{"id":"r"}],
        "columns":[{"id":"a"},{"id":"b"}],"cells":[
            {"row":"r","column":"a","input":input},
            {"row":"r","column":"b","input":"=A1+1"}]}]})
    .to_string()
}

fn call(method: &str, args: Value) -> Result<Value, PluginError> {
    SheetService.call(SERVICE_ID, method, args, &mut MemoryHost::new())
}

#[test]
fn service_uses_the_authoritative_evaluator_without_host_capabilities() {
    let source = source("2");
    let expected =
        serde_json::to_value(Workbook::parse(&source).unwrap().evaluate().unwrap()).unwrap();
    let actual = call(EVALUATE_METHOD, json!({"source":source})).unwrap();
    assert_eq!(actual, expected);
    assert_eq!(
        actual["cells"][1]["value"],
        json!({"kind":"number","value":3.0})
    );
}

#[test]
fn method_version_and_request_shape_are_strict() {
    for (method, args) in [
        ("evaluate_v2", json!({"source":source("2")})),
        (
            EVALUATE_METHOD,
            json!({"source":source("2"),"unknown":true}),
        ),
        (EVALUATE_METHOD, json!({"source":17})),
        (EVALUATE_METHOD, Value::Null),
        (EVALUATE_METHOD, json!({"source":"{}"})),
    ] {
        assert!(matches!(call(method, args), Err(PluginError::BadArgs(_))));
    }
    assert!(matches!(
        SheetService.call(
            "another.service",
            EVALUATE_METHOD,
            json!({"source":source("2")}),
            &mut MemoryHost::new()
        ),
        Err(PluginError::BadArgs(_))
    ));
}

#[test]
fn source_limit_is_enforced_without_poisoning_later_calls() {
    assert!(matches!(
        call(
            EVALUATE_METHOD,
            json!({"source":" ".repeat(MAX_SOURCE_BYTES+1)})
        ),
        Err(PluginError::BadArgs(_))
    ));
    assert!(call(EVALUATE_METHOD, json!({"source":source("4")})).is_ok());
}

#[test]
fn response_limit_counts_repeated_derived_values_and_json_escaping() {
    // Una sola stringa persistita, riusata da dieci formule: la risposta è
    // molto più grande della sorgente. Non deve diventare un Value fuori tetto.
    let input = "x\u{0001}".repeat(150_000);
    let mut workbook: Value = serde_json::from_str(&source(&input)).unwrap();
    let sheet = &mut workbook["sheets"][0];
    sheet["columns"] = json!((0..12)
        .map(|i| json!({"id":format!("c{i}")}))
        .collect::<Vec<_>>());
    sheet["cells"] = json!((0..12)
        .map(|i| json!({"row":"r","column":format!("c{i}"),
        "input":if i==0 {input.clone()} else {"=A1".to_owned()}}))
        .collect::<Vec<_>>());
    let source = workbook.to_string();
    assert!(source.len() < MAX_SOURCE_BYTES);
    assert!(matches!(
        call(EVALUATE_METHOD, json!({"source":source})),
        Err(PluginError::BadArgs(_))
    ));
}

