/// Porta della shell verso il registro servizi. Il provider riceve il
/// proprio HostApi guardato, mai i privilegi del chiamante della shell.
pub fn call_service(
    &self,
    vault: Option<&str>,
    service: &str,
    method: &str,
    args: serde_json::Value,
) -> Result<serde_json::Value, PluginError> {
    let workspace = self.with_session(vault, |session| session.workspace.clone())?;
    let _turn = workspace.write_turn();
    let mut prepared = {
        let mut ws = workspace.write()?;
        ws.prepare_service_call(service, method, args)?
    };
    let mut detached = JobHost::new(workspace.clone(), prepared.owner().to_string());
    let outcome = prepared.invoke(&mut detached);
    let deferred = {
        let mut ws = workspace.write()?;
        ws.finish_service_call_deferred(prepared, outcome)
    };
    finish_events(&workspace, deferred)?
}

//! Adattamento del formato foglio al confine operativo dell'host.
use fub_abi::PluginError;
use fub_format_sheet::Workbook;
pub use fub_format_sheet::session::*;

#[test]
fn shell_service_releases_both_workspace_guards() {
    let vault = vault();
    let (host, workspace) = open(&vault);
    let (probe, entered, release) = boundary(&workspace);
    register_service(&workspace, Box::new(BlockingService(probe.clone())));
    let (observed, outcome) = run_blocked(&workspace, entered, release, move || {
        host.call_service(None, SERVICE, "probe", serde_json::Value::Null)
    });
    probe.detach_workspace();
    assert_both_guards_released(observed);
    assert_eq!(outcome.unwrap(), serde_json::json!({ "status": "ok" }));
    assert_workspace_reusable(&workspace);
}

#[test]
fn shell_service_restores_stack_after_error_and_panic() {
    for failure in [FirstFailure::Error, FirstFailure::Panic] {
        let vault = vault();
        let (host, workspace) = open(&vault);
        register_service(
            &workspace,
            Box::new(RecoveringService {
                failure,
                calls: AtomicUsize::new(0),
            }),
        );
        let (error, recovered) = two_calls_with_cleanup(&workspace, move || {
            host.call_service(None, SERVICE, "probe", serde_json::Value::Null)
        });
        assert!(matches!(
            error,
            PluginError::BadArgs(_) | PluginError::Internal(_)
        ));
        assert_eq!(recovered, serde_json::json!({ "recovered": true }));
    }
}
